import { parseAmount, totalsByCategory } from "../src/ledger.js";

test("parseAmount converts valid amounts to integer cents", () => {
	for (const [text, expected] of [
		["12", 1200], ["12.50", 1250], ["-0.07", -7],
		["-12", -1200], ["0.01", 1], ["0", 0], ["0.00", 0],
		["-0", 0], ["-0.00", 0], ["0012.50", 1250],
		["90071992547409.91", Number.MAX_SAFE_INTEGER],
		["-90071992547409.91", Number.MIN_SAFE_INTEGER],
	]) {
		assert.equal(parseAmount(text), expected, text);
		assert.ok(Number.isSafeInteger(parseAmount(text)), text);
	}
});

test("parseAmount rejects invalid syntax without coercion or trimming", () => {
	for (const text of [
		"", "-", "12.5", "1,200.00", "12.505", "12.", ".50",
		"-.50", "+12", "--12", "1e2", "0x10", "NaN", "Infinity",
		" 12", "12 ", "12\n", "12\r\n", "12\t", "1 2", "１２",
		null, undefined, 12, {}, [],
	]) {
		assert.throws(() => parseAmount(text), /^Error: ledger: invalid amount$/);
	}
});

test("parseAmount rejects cents outside the safe integer range", () => {
	for (const text of [
		"90071992547409.92", "-90071992547409.92",
		"90071992547410", "999999999999999999999999999999.99",
	]) {
		assert.throws(() => parseAmount(text), /^Error: ledger: amount out of range$/);
	}
});

