import { test } from "node:test";
import { parseCsv } from "../src/csv.js";

test("CSV import defaults currency when optional metadata is absent", () => {
	for (const csv of [
		"date;payee;amount;memo\n2026-10-19;Fresh Market;29.66;Groceries",
