	const transaction = { payee: "Fresh Market", amount_cents: -2966 };
	assert.equal(categorize(transaction, [
		{ matches: t => t.payee === "Other", category: "Other" },
		{ matches: t => t.payee === "Fresh Market", category: "Groceries" },
		{ matches: () => { throw new Error("should not run"); }, category: "Later" },
	]), "groceries");
});

test("categorize defaults to uncategorized", () => {
	assert.equal(categorize({}, []), "uncategorized");
	assert.equal(categorize({}, [{ matches: () => false, category: "Other" }]), "uncategorized");
});

test("category Maps safely group prototype names and case variants", () => {
	const transactions = ["__proto__", "__PROTO__", "Constructor", "toString"].map(category => ({
