import assert from "node:assert/strict";
import { test } from "node:test";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

const cli = new URL("../src/cli.js", import.meta.url);
function report(home, ...args) {
	return spawnSync(process.execPath, [cli.pathname, "report", ...args], {
		env: { ...process.env, LEDGER_HOME: home }, encoding: "utf8",
	});
}

test("report --since filters inclusively and prints spend in cents", () => {
	const home = mkdtempSync(join(tmpdir(), "ledger-test-"));
	try {
		writeFileSync(join(home, "transactions.json"), JSON.stringify([
			{ date: "2024-02-28", category: "food", amount_cents: -999 },
			{ date: "2024-02-29", category: "food", amount_cents: -200 },
			{ date: "2024-03-01", category: "food", amount_cents: 50 },
			{ date: "2024-03-02", category: "books", amount_cents: -300 },
		]));
		const result = report(home, "--since", "2024-02-29");
		assert.equal(result.status, 0, result.stderr);
		assert.equal(result.stdout, "books\t300\nfood\t150\n");
		assert.equal(result.stderr, "");
		assert.equal(report(home, "--since", "2025-01-01").stdout, "");
	} finally {
		rmSync(home, { recursive: true, force: true });
	}
});

test("report rejects missing, malformed and impossible since dates before reading data", () => {
	for (const value of [undefined, "", "2023-02-29", "2024-02-30", "2024-04-31", "2024-13-01", "2024-00-01", "2024-01-00", "2024-1-01", "2024-01-01T00:00:00Z", "garbage"]) {
		const result = report("/nonexistent-ledger-test", "--since", ...(value === undefined ? [] : [value]));
		assert.equal(result.status, 1, value);
		assert.match(result.stderr, /^ledger: --since requires a valid date in YYYY-MM-DD format\n$/);
		assert.equal(result.stdout, "");
	}
});

