// CSV import accepts comma or semicolon delimiters and an optional JSON meta column.

export function splitLine(line, delimiter = ";") {
	const cells = [];
	let cell = "";
	let quoted = false;
	for (let i = 0; i < line.length; i++) {
		const char = line[i];
		if (char === '"' && (quoted || cell === "")) {
			if (quoted && line[i + 1] === '"') {
				cell += '"';
				i++;
			} else {
				quoted = !quoted;
			}
		} else if (char === delimiter && !quoted) {
			cells.push(cell);
			cell = "";
		} else {
			cell += char;
		}
	}
	if (quoted) throw new Error("ledger: unterminated quoted CSV field");
	cells.push(cell);
	return cells;
}

/** Parse CSV text into normalized rows. */
export function parseCsv(text) {
	const lines = text.split(/\r?\n/).filter(Boolean);
	const headerLine = lines.shift() ?? "";
	const delimiter = splitLine(headerLine, ",").length > 1 ? "," : ";";
	const header = splitLine(headerLine, delimiter);
	const rows = [];
	for (const line of lines) {
		const cells = splitLine(line, delimiter);
		const record = {};
		header.forEach((name, i) => {
			record[name] = cells[i];
		});
		if (record.meta) record.meta = JSON.parse(record.meta);
		rows.push(normalizeRow(record));
	}
	return rows;
}

export function normalizeRow(record) {
	// Currency defaults to the account currency when the export does not say.
	const currency = record.meta?.currency ?? "EUR";
	return { date: record.date, payee: record.payee, amount: record.amount, memo: record.memo, currency };
}

#!/usr/bin/env node
import { readFileSync } from "node:fs";
import { parseCsv } from "./csv.js";
import { homedir } from "node:os";
import { join } from "node:path";
import { totalsByCategory } from "./ledger.js";

const [command, ...args] = process.argv.slice(2);

function main() {
	switch (command) {
		case "import": {
			const rows = parseCsv(readFileSync(args[0], "utf8"));
			console.log(`imported ${rows.length} rows`);
			return 0;
		}
		case "report": {
			let since;
			for (let i = 0; i < args.length; i++) {
				if (args[i] !== "--since" || since !== undefined) {
					console.error(`ledger: unknown or repeated option: ${args[i]}`);
					return 1;
				}
				since = args[++i];
				if (!since || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(since) ||
					!Number.isFinite(Date.parse(since)) || new Date(since).toISOString().slice(0, 10) !== since) {
					console.error("ledger: --since requires a valid date in YYYY-MM-DD format");
					return 1;
				}
			}
			let transactions;
			try {
				transactions = JSON.parse(readFileSync(join(process.env.LEDGER_HOME ?? join(homedir(), ".ledger"), "transactions.json"), "utf8"));
				if (!Array.isArray(transactions)) throw new Error("invalid transactions");
			} catch {
				console.error("ledger: unable to read transaction data");
				return 2;
			}
			const now = new Date();
			const month = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
			const filtered = transactions.filter(t => since !== undefined ? t.date >= since : t.date.startsWith(`${month}-`));
			const totals = [...totalsByCategory(filtered)].map(([category, cents]) => [category, -cents]);
			totals.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
			for (const [category, cents] of totals) console.log(`${category}\t${cents}`);
			return 0;
		}
		default:
			console.error(`ledger: unknown command: ${command}`);
			return 1;
	}
}

process.exitCode = main();

