test("import handles invalid arguments and input without native stack traces", () => {
	const home = mkdtempSync(join(tmpdir(), "ledger-test-"));
	try {
		const bad = join(home, "bad.csv");
		writeFileSync(bad, 'date,payee,amount,memo,meta\n2024-01-01,Shop,12,,{bad}');
		const quoted = join(home, "quoted.csv");
		writeFileSync(quoted, 'date,payee,amount\n2024-01-01,"Shop,12');
		for (const args of [[], [bad, "extra"], [join(home, "missing.csv")], [bad], [quoted]]) {
			const result = spawnSync(process.execPath, [cli.pathname, "import", ...args], { encoding: "utf8" });
			assert.equal(result.status, 1);
			assert.match(result.stderr, /^ledger: [^\n]+\n$/);
			assert.equal(result.stdout, "");
		}
	} finally {
		rmSync(home, { recursive: true, force: true });
	}
});

test("report rejects corrupt records and unsafe totals as data errors", () => {
	const home = mkdtempSync(join(tmpdir(), "ledger-test-"));
	const valid = { date: "2024-01-01", category: "food", amount_cents: -100 };
	try {
		for (const data of [
			[null], [{}], [{ ...valid, date: "2024-02-30" }],
			[{ ...valid, date: 123 }], [{ ...valid, category: null }],
			[{ ...valid, amount_cents: "100" }], [{ ...valid, amount_cents: 1.5 }],
			[{ ...valid, amount_cents: Number.MAX_SAFE_INTEGER + 1 }],
			[{ ...valid, amount_cents: Number.MAX_SAFE_INTEGER }, { ...valid, amount_cents: 1 }],
			[{ ...valid, amount_cents: Number.MIN_SAFE_INTEGER }, { ...valid, amount_cents: -1 }],
		]) {
			writeFileSync(join(home, "transactions.json"), JSON.stringify(data));
			const result = report(home, "--since", "2024-01-01");
			assert.equal(result.status, 2, JSON.stringify(data));
			assert.match(result.stderr, /^ledger: [^\n]+\n$/);
			assert.equal(result.stdout, "");
		}
	} finally {
		rmSync(home, { recursive: true, force: true });
	}
});

