test("balance sorts case-sensitive accounts and formats exact cent balances", () => {
	const home = mkdtempSync(join(tmpdir(), "ledger-test-"));
	const run = (...args) => spawnSync(process.execPath, [cli.pathname, "balance", ...args], {
		env: { ...process.env, LEDGER_HOME: home }, encoding: "utf8",
	});
	try {
		writeFileSync(join(home, "transactions.json"), JSON.stringify([
			{ account: "checking", amount_cents: -7 },
			{ account: "Credit Card", amount_cents: -12345 },
			{ account: "Checking", amount_cents: 10000 },
			{ account: "Checking", amount_cents: -99 },
			{ account: "__proto__", amount_cents: 0 },
			{ account: "Large", amount_cents: Number.MAX_SAFE_INTEGER },
			{ account: "Large", amount_cents: Number.MAX_SAFE_INTEGER },
		]));
		const result = run();
		assert.equal(result.status, 0, result.stderr);
		assert.equal(result.stderr, "");
		assert.equal(result.stdout, "Checking\t99.01\nCredit Card\t-123.45\nLarge\t180143985094819.82\n__proto__\t0.00\nchecking\t-0.07\n");
		assert.equal(run("extra").status, 1);
		writeFileSync(join(home, "transactions.json"), "[]");
		assert.equal(run().stdout, "");
		for (const data of ["not JSON", "{}", "[null]", '[{"account":"Checking","amount_cents":"100"}]', '[{"amount_cents":100}]']) {
			writeFileSync(join(home, "transactions.json"), data);
			const invalid = run();
			assert.equal(invalid.status, 2);
			assert.match(invalid.stderr, /^ledger: [^\n]+\n$/);
			assert.equal(invalid.stdout, "");
		}
		rmSync(join(home, "transactions.json"));
		assert.equal(run().status, 2);
	} finally {
		rmSync(home, { recursive: true, force: true });
	}
});

